import torch,torch.nn as nn; exec("class Solution:\n    def compute_activation_stats(self, model, x):\n        stats = []\n        with torch.no_grad():\n            h = x\n            for layer in model:\n                h = layer(h)\n                if isinstance(layer, nn.Linear):\n                    stats.append({'mean': round(float(h.mean()), 4), 'std': round(float(h.std()), 4), 'dead_fraction': round(float((h <= 0).all(dim=0).float().mean()), 4)})\n        return stats\n    def compute_gradient_stats(self, model, x, y):\n        stats = []\n        model.zero_grad()\n        out = model(x)\n        loss = nn.MSELoss()(out, y)\n        loss.backward()\n        for layer in model:\n            if isinstance(layer, nn.Linear):\n                g = layer.weight.grad\n                stats.append({'mean': round(float(g.mean()), 4), 'std': round(float(g.std()), 4), 'norm': round(float(torch.norm(g)), 4)})\n        return stats\n    def diagnose(self, activation_stats, gradient_stats):\n        for s in activation_stats:\n            if s['dead_fraction'] > 0.5:\n                return 'dead_neurons'\n        for s in gradient_stats:\n            if s['norm'] > 1000:\n                return 'exploding_gradients'\n        if gradient_stats and gradient_stats[-1]['norm'] < 1e-5:\n            return 'vanishing_gradients'\n        for s in activation_stats:\n            if s['std'] < 0.1:\n                return 'vanishing_gradients'\n            if s['std'] > 10.0:\n                return 'exploding_gradients'\n        return 'healthy'")